int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent)
{
    struct net_device *netdev;
    int err;

    err = pci_enable_device(pdev);
    if (err < 0)
        return err;

    if (pci_set_dma_mask(pdev, DMA_32BIT) < 0 || pci_set_consistent_dma_mask(pdev, DMA_32BIT) < 0) {
        pci_disable_device(pdev);
        return -ENODEV;
    }

    err = pci_request_regions(pdev, "atl2");
    if (err < 0) {
        pci_disable_device(pdev);
        return err;
    }

    netdev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!netdev) {
        pci_release_regions(pdev);
        pci_disable_device(pdev);
        return -ENOMEM;
    }

    SET_NETDEV_DEV(netdev, &pdev->dev);
    netdev->irq = pdev->irq;

    netdev->netdev_ops = &atl2_netdev_ops;
    netdev->watchdog_timeo = 5 * HZ;
    netdev->priv = netdev->ml_priv;

    err = register_netdev(netdev);
    if (err < 0) {
        free_netdev(netdev);
        pci_release_regions(pdev);
        pci_disable_device(pdev);
        return err;
    }

    return 0;
}

int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent) {
    struct net_device *netdev;
    int err;

    err = pci_enable_device(pdev);
    if (err)
        return err;

    if ((err = pci_set_dma_mask(pdev, DMA_BIT_MASK(32))) != 0) {
        if ((err = pci_set_consistent_dma_mask(pdev, DMA_BIT_MASK(32))) != 0)
            goto err_dma;
    }

    if (!request_pci_region(pdev, "atl2")) {
        err = -EBUSY;
        goto err_dma;
    }

    netdev = alloc_etherdev(0);
    if (!netdev) {
        err = -ENOMEM;
        goto err_region;
    }

    netdev->irq = pdev->irq;
    netdev->base_addr = pci_resource_start(pdev, 0);

    if ((err = atl2_up(netdev)) != 0)
        goto err_alloc;

    setup_timer(&netdev->watchdog_timer, atl2_watchdog, (unsigned long)netdev);
    setup_timer(&netdev->phy_config_timer, atl2_phy_config, (unsigned long)netdev);

    ether_addr_copy(netdev->dev_addr, atl2_read_mac_address(pdev));
    netdev->flags |= IFF_NOARP;
    netdev->features |= NETIF_F_SG | NETIF_F_IP_CSUM;

    register_netdev(netdev);

    return 0;

err_alloc:
    free_netdev(netdev);
err_region:
    release_pci_region(pdev);
err_dma:
    pci_disable_device(pdev);
    return err;
}

int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent)
{
    int err;
    void __iomem *addr;
    struct net_device *netdev;
    struct atl2_adapter *adapter;

    err = pci_enable_device(pdev);
    if (err)
        return err;

    err = pci_request_regions(pdev, "ATL2");
    if (err)
        goto err_pci_disable;

    addr = pci_iomap(pdev, 0, 0);
    if (!addr) {
        err = -ENOMEM;
        goto err_pci_release;
    }

    netdev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!netdev) {
        err = -ENOMEM;
        goto err_iounmap;
    }

    pci_set_drvdata(pdev, netdev);
    adapter = netdev_priv(netdev);
    adapter->pdev = pdev;
    adapter->hw.back = adapter;
    adapter->hw.hw_addr = addr;

    memcpy(adapter->hw.mac.addr, netdev->dev_addr, ETH_ALEN);

    err = atl2_setup_pci_link(adapter);
    if (err)
        goto err_free_netdev;

    err = atl2_setup_ring_resources(adapter);
    if (err)
        goto err_remove_pci;

    err = atl2_setup_hw_tx_ctx(adapter);
    if (err)
        goto err_free_ring;

    err = atl2_setup_hw_rx_ctx(adapter);
    if (err)
        goto err_free_tx_ring;

    netdev->netdev_ops = &atl2_netdev_ops;
    netdev->watchdog_timeo = TX_WATCHDOG;

    setup_timer(&adapter->watchdog_timer, atl2_watchdog, (unsigned long)adapter);
    setup_timer(&adapter->phy_config_timer, atl2_check_phy_status, (unsigned long)adapter);

    err = register_netdev(netdev);
    if (err)
        goto err_free_timer;

    return 0;

err_free_timer:
    del_timer_sync(&adapter->watchdog_timer);
    del_timer_sync(&adapter->phy_config_timer);
err_free_tx_ring:
    atl2_free_hw_rx_ctx(adapter);
err_free_ring:
    atl2_free_hw_tx_ctx(adapter);
err_remove_pci:
    atl2_remove_pci(adapter);
err_free_netdev:
    free_netdev(netdev);
err_iounmap:
    pci_iounmap(pdev, addr);
err_pci_release:
    pci_release_regions(pdev);
err_pci_disable:
    pci_disable_device(pdev);
    return err;
}

